contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint depositAmount, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0, "deposit must be positive");
        require(collectAmount <= depositAmount, "collect must not exceed deposit");
        require(address(this).balance >= depositAmount, "not enough balance to deposit");

        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint balAfterDeposit = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cEtherAfterDeposit = address(c).balance;
        uint thisEtherAfterDeposit = address(this).balance;

        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balAfterCollect = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cEtherAfterCollect = address(c).balance;
        uint thisEtherAfterCollect = address(this).balance;

        assert(!reverted && balAfterCollect == balAfterDeposit - collectAmount && cEtherAfterCollect == cEtherAfterDeposit - collectAmount && thisEtherAfterCollect == thisEtherAfterDeposit + collectAmount);
    }

    receive() external payable {}
}

